import struct
import collections

def read_stl(file_path):
    with open(file_path, 'rb') as f:
        header = f.read(80)
        num_triangles = struct.unpack('<I', f.read(4))[0]
        triangles = []
        for _ in range(num_triangles):
            data = struct.unpack('<ffffffffffffH', f.read(50))
            v1 = tuple(data[3:6])
            v2 = tuple(data[6:9])
            v3 = tuple(data[9:12])
            attr = data[12]
            triangles.append({'vertices': (v1, v2, v3), 'material_id': attr})
    return triangles

def get_edges(tri):
    v1, v2, v3 = tri['vertices']
    v1 = tuple(round(c, 6) for c in v1)
    v2 = tuple(round(c, 6) for c in v2)
    v3 = tuple(round(c, 6) for c in v3)
    return [tuple(sorted((v1, v2))), tuple(sorted((v2, v3))), tuple(sorted((v3, v1)))]

def main():
    triangles = read_stl('scan_data.stl')
    # Use the same component logic as before to find the largest component
    vertex_to_triangles = collections.defaultdict(list)
    for i, tri in enumerate(triangles):
        for v in tri['vertices']:
            v_rounded = tuple(round(coord, 6) for coord in v)
            vertex_to_triangles[v_rounded].append(i)

    adj = collections.defaultdict(set)
    for i, tri in enumerate(triangles):
        for v in tri['vertices']:
            v_rounded = tuple(round(coord, 6) for coord in v)
            for other_tri_idx in vertex_to_triangles[v_rounded]:
                if other_tri_idx != i:
                    adj[i].add(other_tri_idx)

    visited = [False] * len(triangles)
    components = []
    for i in range(len(triangles)):
        if not visited[i]:
            comp = []
            q = [i]
            visited[i] = True
            while q:
                curr = q.pop(0)
                comp.append(curr)
                for n in adj[curr]:
                    if not visited[n]:
                        visited[n] = True
                        q.append(n)
            components.append(comp)

    components.sort(key=len, reverse=True)
    largest = components[0]

    edge_counts = collections.Counter()
    for idx in largest:
        edges = get_edges(triangles[idx])
        for e in edges:
            edge_counts[e] += 1

    unmatched_edges = [e for e, count in edge_counts.items() if count != 2]
    print(f"Number of triangles: {len(largest)}")
    print(f"Number of edges with count != 2: {len(unmatched_edges)}")
    if unmatched_edges:
        for e in unmatched_edges[:5]:
            print(f"Edge {e} has count {edge_counts[e]}")

if __name__ == "__main__":
    main()
